//! Real GBA, 32X and Mega CD tests (6.0): mgba, picodrive and genesis_plus_gx headless, on free third-party
//! homebrews (`docs/design/donnees-test-4-7.md` §1 to §3) and on discs generated by `tests/tools/mkcd.py`.
//! No BIOS: mgba and picodrive (32X) have theirs built in; the Mega CD tests check the failure without BIOS.
//!
//! All tests are `#[ignore]`: run `scripts/fetch-test-assets.sh --with-6.0` then
//! `cargo test -p emu-runtime --test gba_32x_megacd_real -- --ignored --test-threads=1`. Set
//! `EMU_UPDATE_FINGERPRINTS=1` to (re)write `tests/fingerprints/{gba-mgba,32x-picodrive}.txt` after inspecting the
//! PNGs in `target/test-output/gba-32x-megacd/`.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Mutex, MutexGuard};

use emu_runtime::{
    CollectSink, ContentSpec, Emulator, EmulatorOptions, JoypadButton, LibretroError, M3uLaunch,
    MAX_COPY_BYTES, MediaPolicy, MediaRules, MediaSet, MemoryKind, NullInput, RuntimeError,
    SaveScope, ScriptedInput, prepare_media,
};

/// One libretro core per process (ADR 0008): tests must not overlap.
static LOCK: Mutex<()> = Mutex::new(());

fn lock() -> MutexGuard<'static, ()> {
    LOCK.lock().unwrap_or_else(|e| e.into_inner())
}

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn core_path(core: &str) -> PathBuf {
    root().join(format!("tests/cores/{core}_libretro.so"))
}

fn rom(rel: &str) -> PathBuf {
    root().join("tests/roms").join(rel)
}

fn out_dir(name: &str) -> PathBuf {
    let dir = root().join("target/test-output/gba-32x-megacd").join(name);
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("create output dir");
    dir
}

fn require(path: &Path) -> &Path {
    assert!(
        path.is_file(),
        "missing test asset {}: lancer scripts/fetch-test-assets.sh --with-6.0",
        path.display()
    );
    path
}

fn options(data: &Path) -> EmulatorOptions {
    for sub in ["system", "saves", "states", "assets"] {
        fs::create_dir_all(data.join(sub)).unwrap();
    }
    EmulatorOptions {
        system_dir: data.join("system"),
        save_dir: data.join("saves"),
        cache_dir: data.join("cache"),
        provide_vfs: false,
        state_dir: data.join("states"),
        assets_dir: data.join("assets"),
        core_variables: Vec::new(),
        restore_added_disks: false,
        core_save_scope: SaveScope::Core,
        fastforward_override: false,
        variable_state_size: false,
    }
}

fn load_file(core: &str, content: &Path, data: &Path) -> Result<Emulator, RuntimeError> {
    require(&core_path(core));
    require(content);
    Emulator::load_content(
        &core_path(core),
        ContentSpec::File(content.to_path_buf()),
        options(data),
    )
}

fn run_frames(emu: &mut Emulator, input: &mut dyn emu_runtime::InputBackend, frames: u64) {
    let mut sink = CollectSink::default();
    for _ in 0..frames {
        emu.run_frame(input, &mut sink).expect("run_frame");
    }
}

/// More than one distinct pixel value on the screen.
fn not_blank(emu: &Emulator) -> bool {
    let px = emu.frame().pixels();
    px.as_chunks::<4>().0.iter().any(|p| p[..] != px[..4])
}

// ---- fingerprints (same name-merged format as `cpc_c64_real.rs`) -------------------------------------------

fn core_hash(core: &str) -> String {
    fs::read_to_string(root().join(format!("tests/cores/{core}_libretro.so.sha256")))
        .ok()
        .and_then(|s| s.split_whitespace().next().map(str::to_owned))
        .unwrap_or_else(|| "unknown".into())
}

fn parse_prints(text: &str) -> Vec<(String, u64, u64)> {
    text.lines()
        .filter(|l| !l.trim().is_empty() && !l.starts_with('#'))
        .map(|l| {
            let mut parts = l.split_whitespace();
            let name = parts.next().unwrap().to_owned();
            let (mut frame, mut fp) = (None, None);
            for part in parts {
                if let Some(v) = part.strip_prefix("frame=") {
                    frame = v.parse().ok();
                } else if let Some(v) = part.strip_prefix("fingerprint=") {
                    fp = u64::from_str_radix(v, 16).ok();
                }
            }
            (
                name,
                frame.unwrap_or_else(|| panic!("bad fingerprint line: {l}")),
                fp.unwrap_or_else(|| panic!("bad fingerprint line: {l}")),
            )
        })
        .collect()
}

fn check_fingerprint(file: &str, core: &str, name: &str, frame: u64, fp: u64) {
    let path = root().join("tests/fingerprints").join(file);
    let mut known = fs::read_to_string(&path)
        .map(|t| parse_prints(&t))
        .unwrap_or_default();
    if std::env::var_os("EMU_UPDATE_FINGERPRINTS").is_some() {
        known.retain(|(n, _, _)| n != name);
        known.push((name.to_owned(), frame, fp));
        known.sort();
        let mut out = format!(
            "# {core}, free homebrews, no BIOS (built into the core); core sha256 {}\n",
            core_hash(core)
        );
        for (n, f, p) in &known {
            out.push_str(&format!("{n} frame={f} fingerprint={p:016x}\n"));
        }
        fs::write(&path, out).unwrap();
        return;
    }
    let want = known
        .iter()
        .find(|(n, _, _)| n == name)
        .unwrap_or_else(|| {
            panic!(
                "no fingerprint `{name}` in {}: inspect target/test-output/gba-32x-megacd/*/*.png then run with EMU_UPDATE_FINGERPRINTS=1",
                path.display()
            )
        });
    assert_eq!(
        (want.1, want.2),
        (frame, fp),
        "fingerprint `{name}` differs; regenerate with EMU_UPDATE_FINGERPRINTS=1 if the change is legitimate"
    );
}

/// One session: loads, plays `frames` frames with `input`, returns `(width, height, fingerprint)` and writes a PNG.
fn session(
    core: &str,
    content: &Path,
    dir: &Path,
    frames: u64,
    mut input: ScriptedInput,
) -> Result<(u32, u32, u64), RuntimeError> {
    let mut emu = load_file(core, content, &dir.join("data"))?;
    run_frames(&mut emu, &mut input, frames);
    assert!(not_blank(&emu), "blank screen after {frames} frames");
    emu.frame().write_png(&dir.join("last.png")).unwrap();
    Ok((
        emu.frame().width(),
        emu.frame().height(),
        emu.frame().fingerprint(),
    ))
}

/// Plays the same session twice, requires identical results, then pins them under `name`.
fn stable(
    file: &str,
    core: &str,
    name: &str,
    content: &Path,
    frames: u64,
    input: &ScriptedInput,
) -> (u32, u32, u64) {
    let a = session(
        core,
        content,
        &out_dir(&format!("{name}-a")),
        frames,
        input.clone(),
    )
    .expect("load");
    let b = session(
        core,
        content,
        &out_dir(&format!("{name}-b")),
        frames,
        input.clone(),
    )
    .expect("load");
    assert_eq!(a, b, "two runs of `{name}` must be identical");
    check_fingerprint(file, core, name, frames, a.2);
    a
}

// ---- GBA (mgba) --------------------------------------------------------------------------------------------

#[test]
#[ignore = "needs mgba and the GBA test data: scripts/fetch-test-assets.sh --with-6.0"]
fn mgba_hello_world_is_stable() {
    let _g = lock();
    let (w, h, _) = stable(
        "gba-mgba.txt",
        "mgba",
        "hello.gba",
        &rom("gba/hello.gba"),
        300,
        &ScriptedInput::new(),
    );
    assert_eq!((w, h), (240, 160));
}

#[test]
#[ignore = "needs mgba and the GBA test data: scripts/fetch-test-assets.sh --with-6.0"]
fn mgba_240p_menu_is_stable_and_reacts_to_input() {
    let _g = lock();
    let path = rom("gba/240pee_mb-0.23.gba");
    let menu = stable(
        "gba-mgba.txt",
        "mgba",
        "240pee_mb.gba",
        &path,
        300,
        &ScriptedInput::new(),
    );
    assert_eq!((menu.0, menu.1), (240, 160));
    // Down then A opens another screen.
    let input = ScriptedInput::new()
        .press(0, JoypadButton::Down, 300..306)
        .press(0, JoypadButton::A, 330..336);
    let after = session("mgba", &path, &out_dir("240pee_mb-input"), 420, input).expect("load");
    assert_ne!(menu.2, after.2, "the screen did not change after Down + A");
}

/// The `.srm` is written and read back. Observed with the pinned mgba: it reports a 32 KiB save RAM for the two
/// Flash test ROMs too (not the 64 / 128 KiB the design expected), so only a lower bound is required for them.
#[test]
#[ignore = "needs mgba and the GBA test data: scripts/fetch-test-assets.sh --with-6.0"]
fn mgba_save_roms_write_and_reload_the_srm() {
    let _g = lock();
    for (name, min_size) in [
        ("sram.gba", 32 * 1024),
        ("flash64.gba", 32 * 1024),
        ("flash128.gba", 32 * 1024),
    ] {
        let data = out_dir(&format!("save-{name}"));
        let srm = {
            let mut emu = load_file("mgba", &rom(&format!("gba/{name}")), &data).expect("load");
            run_frames(&mut emu, &mut NullInput, 300);
            let srm = emu.sram_path();
            assert!(
                emu.flush_sram().expect("flush") || srm.is_file(),
                "{name}: nothing written"
            );
            srm
        };
        assert!(srm.is_file(), "{name}: no .srm at {}", srm.display());
        assert!(srm.starts_with(data.join("saves").join("mgba")));
        let written = fs::read(&srm).unwrap();
        let size = written.len();
        assert!(
            size >= min_size && [32 << 10, 64 << 10, 128 << 10].contains(&size),
            "{name}: .srm size {size}"
        );
        assert!(
            written.iter().any(|b| *b != 0 && *b != 0xFF),
            "{name}: the ROM wrote nothing into the save"
        );

        // A second session starts from the file (and does not rewrite it identically).
        let mut emu = load_file("mgba", &rom(&format!("gba/{name}")), &data).expect("reload");
        // mgba exposes a 128 KiB buffer until it has seen the ROM use its save type: the file is its prefix.
        let loaded = emu.memory(MemoryKind::SaveRam).expect("save RAM exposed");
        assert_eq!(
            &loaded[..size],
            written.as_slice(),
            "{name}: save not reloaded"
        );
        run_frames(&mut emu, &mut NullInput, 60);
        let _ = emu.flush_sram();
        drop(emu);
        assert_eq!(
            fs::read(&srm).unwrap().len(),
            size,
            "{name}: .srm size after reload"
        );
    }
}

#[test]
#[ignore = "needs mgba and the GBA test data: scripts/fetch-test-assets.sh --with-6.0"]
fn mgba_rom_without_save_writes_no_srm() {
    let _g = lock();
    let data = out_dir("save-none");
    let mut emu = load_file("mgba", &rom("gba/none.gba"), &data).expect("load");
    run_frames(&mut emu, &mut NullInput, 300);
    let srm = emu.sram_path();
    let _ = emu.flush_sram();
    drop(emu);
    // mgba may expose a default-sized RAM for an unknown save type; if so it is blank (never written by the ROM).
    if srm.is_file() {
        let bytes = fs::read(&srm).unwrap();
        assert!(
            bytes.iter().all(|b| *b == 0 || *b == 0xFF),
            "none.gba: unexpected save content"
        );
    }
}

// ---- 32X (picodrive) ---------------------------------------------------------------------------------------

#[test]
#[ignore = "needs picodrive and hexgl32x: scripts/fetch-test-assets.sh --with-6.0"]
fn picodrive_32x_homebrew_starts_and_the_image_changes() {
    let _g = lock();
    let path = rom("32x/hexgl32x-0.0.1.32x");
    let dir = out_dir("hexgl32x-probe");
    let emu = match load_file("picodrive", &path, &dir) {
        Ok(emu) => emu,
        Err(e) => {
            // Design v6.0 §7: the ROM was never tried on picodrive before GQ2; a rejection is reported, not hidden.
            eprintln!("SKIPPED: picodrive rejects hexgl32x: {e}");
            return;
        }
    };
    assert!(emu.system_info().library_name.contains("PicoDrive"));
    drop(emu);

    let input = ScriptedInput::new().press(0, JoypadButton::Start, 300..310);
    let title = stable(
        "32x-picodrive.txt",
        "picodrive",
        "hexgl32x-title",
        &path,
        300,
        &ScriptedInput::new(),
    );
    let started =
        session("picodrive", &path, &out_dir("hexgl32x-start"), 600, input).expect("load");
    assert_ne!(title.2, started.2, "the image did not change after Start");
}

// ---- Mega CD without BIOS ----------------------------------------------------------------------------------

/// Names, sizes and content hashes of every file below `dir`.
fn tree(dir: &Path) -> BTreeMap<String, (u64, u64)> {
    fn walk(dir: &Path, base: &Path, out: &mut BTreeMap<String, (u64, u64)>) {
        for entry in fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() {
                walk(&path, base, out);
            } else {
                let bytes = fs::read(&path).unwrap();
                // FNV-1a is enough to compare a file with itself before and after.
                let h = bytes.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, b| {
                    (h ^ u64::from(*b)).wrapping_mul(0x0100_0000_01b3)
                });
                let rel = path
                    .strip_prefix(base)
                    .unwrap()
                    .to_string_lossy()
                    .into_owned();
                out.insert(rel, (bytes.len() as u64, h));
            }
        }
    }
    let mut out = BTreeMap::new();
    walk(dir, dir, &mut out);
    out
}

fn core_error_of(result: Result<Emulator, RuntimeError>) -> String {
    match result {
        Ok(_) => panic!("the core started a Mega CD disc without BIOS"),
        Err(RuntimeError::Libretro(LibretroError::LoadGameFailed { core_error, .. })) => {
            core_error.expect("the core's error text is captured (core_error)")
        }
        Err(other) => panic!("unexpected error: {other}"),
    }
}

#[test]
#[ignore = "needs genesis_plus_gx and the 240p discs: scripts/fetch-test-assets.sh --with-6.0"]
fn megacd_without_bios_asks_for_the_bios_of_the_disc_region() {
    let _g = lock();
    for (folder, cue, bios) in [
        (
            "240pSuite-SegaCD-1.21-USA",
            "240pSuite_USA.cue",
            "bios_CD_U.bin",
        ),
        (
            "240pSuite-SegaCD-1.21-EUR",
            "240pSuite_EU.cue",
            "bios_CD_E.bin",
        ),
        (
            "240pSuite-SegaCD-1.21-JPN",
            "240pSuite_JP.cue",
            "bios_CD_J.bin",
        ),
    ] {
        let disc_dir = rom(folder);
        let before = tree(&disc_dir);
        let data = out_dir(&format!("nobios-{bios}"));
        let text = core_error_of(load_file("genesis_plus_gx", &disc_dir.join(cue), &data));
        assert!(text.contains(bios), "{cue}: `{text}` does not name {bios}");
        assert_eq!(
            tree(&disc_dir),
            before,
            "{cue}: the disc folder was modified"
        );
        // No BIOS was provided, none appeared (the core never writes into the system folder).
        assert_eq!(fs::read_dir(data.join("system")).unwrap().count(), 0);
    }
}

#[test]
#[ignore = "needs picodrive and the 240p disc: scripts/fetch-test-assets.sh --with-6.0"]
fn picodrive_megacd_without_bios_reports_the_core_error() {
    let _g = lock();
    let disc_dir = rom("240pSuite-SegaCD-1.21-USA");
    let before = tree(&disc_dir);
    let text = core_error_of(load_file(
        "picodrive",
        &disc_dir.join("240pSuite_USA.cue"),
        &out_dir("nobios-picodrive"),
    ));
    assert!(!text.trim().is_empty());
    assert_eq!(tree(&disc_dir), before);
}

fn mkcd(args: &[&str]) {
    let run = Command::new("python3")
        .arg("-I")
        .arg(root().join("tests/tools/mkcd.py"))
        .args(args)
        .output()
        .expect("python3 is required to run the media generators");
    assert!(
        run.status.success(),
        "mkcd.py failed: {}",
        String::from_utf8_lossy(&run.stderr)
    );
}

/// Media policy of genesis_plus_gx / picodrive (`cores.toml`: `media_direct = ["cue", "chd", "iso"]`).
fn direct_rules() -> MediaRules {
    MediaRules {
        policy: MediaPolicy::Direct,
        media_direct: ["cue", "chd", "iso"].map(str::to_owned).to_vec(),
        max_copy_bytes: MAX_COPY_BYTES,
        m3u_launch: M3uLaunch::None,
    }
}

#[test]
#[ignore = "needs genesis_plus_gx: scripts/fetch-test-assets.sh --with-6.0"]
fn two_disc_playlist_is_handed_over_in_place_and_nothing_is_copied() {
    let _g = lock();
    let discs = out_dir("m3u-discs");
    mkcd(&[
        "megacd",
        discs.to_str().unwrap(),
        "--name",
        "Game",
        "--discs",
        "2",
        "--region",
        "E",
        "--iso",
    ]);
    let m3u = discs.join("Game.m3u");
    assert!(m3u.is_file());
    let before = tree(&discs);
    let set = MediaSet {
        name: "Game".into(),
        images: Vec::new(),
        playlist: Some(m3u.clone()),
        launch: None,
    };

    // Preparation alone: the user's playlist as is, no copy, no temporary directory, no working folder.
    let saves = out_dir("m3u-saves").join("genesis_plus_gx");
    fs::create_dir_all(&saves).unwrap();
    let accepted = ["cue", "chd", "iso", "m3u"].map(str::to_owned).to_vec();
    let prepared = prepare_media(&set, &direct_rules(), &accepted, &saves).expect("prepare");
    assert_eq!(prepared.content, m3u);
    assert!(prepared.work_dir.is_none() && prepared.temp_dir().is_none());
    assert_eq!(
        fs::read_dir(&saves).unwrap().count(),
        0,
        "something was copied"
    );

    // Through the emulator (no BIOS): the core's error is reported, the discs are untouched, nothing copied.
    let data = out_dir("m3u-data");
    let result = Emulator::load_content(
        &core_path("genesis_plus_gx"),
        ContentSpec::Media {
            set,
            rules: direct_rules(),
        },
        options(&data),
    );
    let text = core_error_of(result);
    // With a playlist genesis_plus_gx logs the BIOS error, then "Could not load <first disc> from M3U file list"
    // (the last error is the one kept): either way the first disc is what it names, or the BIOS.
    assert!(
        text.contains("bios_CD_E.bin") || text.contains("Game (Disc 1).cue"),
        "`{text}`"
    );
    assert_eq!(tree(&discs), before, "the disc folder was modified");
    let copies: Vec<_> = walk_names(&data.join("saves"))
        .into_iter()
        .filter(|n| n.ends_with(".disks") || n.ends_with(".cue") || n.ends_with(".iso"))
        .collect();
    assert!(copies.is_empty(), "copied: {copies:?}");
}

fn walk_names(dir: &Path) -> Vec<String> {
    let mut out = Vec::new();
    if let Ok(read) = fs::read_dir(dir) {
        for entry in read.flatten() {
            out.push(entry.file_name().to_string_lossy().into_owned());
            if entry.path().is_dir() {
                out.extend(walk_names(&entry.path()));
            }
        }
    }
    out
}
